/* ============================================================
   SERVICE PROCESS — service-process.module.css
   ============================================================ */

.section {
  background-color: #f5f7fa;
  padding: 80px 5% 90px;
  overflow: hidden;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* Header */
.header {
  text-align: center;
  max-width: 720px;
  margin-left: auto;
  margin-right: auto;
  margin-bottom: 56px;
}

.badgeRow {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.badge {
  background-color: rgba(33, 207, 255, 0.07);
  border: 1px solid #05bafe;
  border-radius: 20px;
  padding: 0 14px;
  line-height: 34px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  margin: 0;
  font-size: 12px;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-weight: 600;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.heading {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 16px;
}

.subtitle {
  color: #4b5563;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 16px;
  line-height: 1.75;
}

/* Steps grid — 4 columns */
.stepsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  grid-column-gap: 32px;
  grid-row-gap: 48px;
}

.step {
  position: relative;
  text-align: center;
}

/* Dashed connector between steps */
.step:not(:last-child)::after {
  content: '';
  display: block;
  position: absolute;
  top: 22px;
  right: -16px;
  width: 32px;
  height: 1px;
  border-top: 2px dashed #d1d5db;
}

/* Number circle */
.numberCircle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid rgba(33, 207, 255, 0.4);
  background-color: #fff;
  margin: 0 auto 20px;
}

.number {
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.stepTitle {
  color: #092245;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 10px;
}

.stepText {
  color: #4b5563;
  font-family: 'Roobert PRO', Arial, sans-serif;
  font-size: 15px;
  font-weight: 400;
  line-height: 1.65;
  margin: 0;
}

/* ============================================================
   max-width: 1199px
   ============================================================ */
@media screen and (max-width: 1199px) {
  .stepsGrid {
    grid-template-columns: 1fr 1fr;
    max-width: 720px;
    margin-left: auto;
    margin-right: auto;
  }

  .step:not(:last-child)::after {
    display: none;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .section {
    padding: 60px 5% 70px;
  }

  .heading {
    font-size: 2rem;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .stepsGrid {
    grid-template-columns: 1fr;
    max-width: 480px;
    grid-row-gap: 36px;
  }

  .header {
    margin-bottom: 36px;
  }

  .heading {
    font-size: 1.75rem;
    line-height: 1.25;
  }
}

/* ============================================================
   max-width: 479px
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding: 48px 1.25rem 56px;
  }

  .heading {
    font-size: 1.5rem;
  }

  .subtitle {
    font-size: 0.9375rem;
  }
}

